import java.io.*;

public class D {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        long n = nextLong(reader);
        long m = nextLong(reader);
        System.out.println(compute(n, m));
    }

    static long nextLong(Reader reader) throws IOException {
        int c;
        do {
            c = reader.read();
        } while (c != -1 && Character.isWhitespace(c));
        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = reader.read();
        }
        long value = 0;
        while (c != -1 && !Character.isWhitespace(c)) {
            value = value * 10 + (c - '0');
            c = reader.read();
        }
        return negative ? -value : value;
    }

    static long compute(long n, long m) {
        if (m < n) {
            n = n ^ m;
            m = n ^ m;
            n = n ^ m;
        }
        if (n == 1) return bruteRow(m);
        if (n == 2) {
            if (m < 3) return 0;
            if (m == 3) return 4;
            if (m == 7) return 12;
            return 2 * m;
        }
        return 2 * (n * m / 2);
    }

    static long bruteRow(long m) {
        return 6 * (m / 6) + (m % 6 == 5 ? 4 : m % 6 == 4 ? 2 : 0);
    }
}
